```javascript
const { Client, Intents, GatewayIntentBits } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.on('ready', () => {
  console.log(`Bot en ligne! Nom: ${client.user.username}`);
});

client.on('interactionCreate', async (interaction) => {
  if (!interaction.isChatInputCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'bannir') {
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'Vous n'avez pas les permissions de bannir des utilisateurs.', ephemeral: true });
    }

    const member = interaction.options.getMember('utilisateur');

    if (!member) {
      return interaction.reply({ content: 'Veuillez spécifier un utilisateur à bannir.', ephemeral: true });
    }

    if (member.permissions.has('ADMINISTRATOR') || member.id === interaction.guild.ownerId) {
      return interaction.reply({ content: 'Vous ne pouvez pas bannir cet utilisateur.', ephemeral: true });
    }

    try {
      await member.ban({ reason: `Banni(e) par ${interaction.user.tag}` });
      await interaction.reply({ content: `L'utilisateur ${member.user.tag} a été banni(e) avec succès.`, ephemeral: true });
    } catch (error) {
      console.error(error);
      await interaction.reply({ content: 'Une erreur est survenue pendant le bannissement de l\'utilisateur. Veuillez réessayer ultérieurement.', ephemeral: true });
    }
  }
});

client.login(process.env.TOKEN);
```

