Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <regex>
#include <boost/algorithm/string.hpp>

std::string convertMarkdownToHtml(const std::string& markdown) {
    std::string html;

    // Titres
    std::regex title_regex(R"(^(#{1,6}) +(.*)$)", std::regex::icase);
    std::smatch title_match;

    if (std::regex_search(markdown, title_match, title_regex)) {
        std::string level = title_match[1].str();
        std::string text = title_match[2].str();

        std::string tag = "h" + (level.size() - 1);
        boost::algorithm::replace_all(text, "\n", "");

        html += "<" + tag + " class='markdown-h' >" + text + "</" + tag + ">\n";
    }

    // Gras
    std::regex bold_regex(R"(__(.*)__)", std::regex::icase);
    std::smatch bold_match;

    if (std::regex_search(markdown, bold_match, bold_regex)) {
        std::string text = bold_match[1].str();

        html += "<strong>" + text + "</strong>\n";
    }

    // Italique
    std::regex italic_regex(R"(__(.*)__)", std::regex::icase);
    std::smatch italic_match;

    if (std::regex_search(markdown, italic_match, italic_regex)) {
        std::string text = italic_match[1].str();

        html += "<em>" + text + "</em>\n";
    }

    // Code
    std::regex code_regex(R"(`(.*)`)", std::regex::icase);
    std::smatch code_match;

    if (std::regex_search(markdown, code_match, code_regex)) {
        std::string text = code_match[1].str();

        html += "<code>" + text + "</code>\n";
    }

    // Lien
    std::regex link_regex(R"((\[.*?\])(\().*?\))", std::regex::icase);
    std::smatch link_match;

    while (std::regex_search(markdown, link_match, link_regex)) {
        std::string label = link_match[1].str();
        std::string href = link_match[2].str();

        boost::algorithm::replace_all(href, "\"", "&quot;");

        html += "<a href='" + href + "' class='markdown-link'>" + label + "</a>\n";

        markdown = std::regex_replace(markdown, link_regex, "");
    }

    // Bloc de code
    std::regex block_code_regex(R"(```(.*?)\n([\s\S]*?)```)", std::regex::icase);
    std::smatch block_code_match;

    if (std::regex_search(markdown, block_code_match, block_code_regex)) {
        std::string language = block_code_match[1].str();
        std::string content = block_code_match[2].str();

        html += "<pre class='language-" + language + "'><code>" + content + "</code></pre>\n";
    }

    // Bloc de texte
    std::regex block_text_regex(R"(^> (.*)$)", std::regex::icase);
    std::smatch block_text_match;

    if (std::regex_search(markdown, block_text_match, block_text_regex)) {
        std::string text = block_text_match[1].str();

        html += "<p class='markdown-block'>" + text + "</p>\n";
    }

    // Retour à la ligne
    std::regex newline_regex(R"(\\n)", std::regex::icase);
    std::string newlines = std::regex_replace(markdown, newline_regex, "<br>\n");

    html += newlines;

    return html;
}

int main() {
    std::string markdown = "Titre de niveau 2 ## Titre\n\nGras **texte**\n\nItalique *texte*\n\nCode `console.log('Hello, world!')`\n\nLien [Google](https://www.google.com/)\n\nBloc de code\n```javascript\nconsole.log('Hello, world!');\n```\n\nBloc de texte\n> Cela est un bloc de texte.";

    std::string html = convertMarkdownToHtml(markdown);

    std::cout << html << std::endl;

    return 0;
}
```

Cette fonction utilise la bibliothèque Boost pour effectuer des opérations de remplacement de chaîne et la bibliothèque Boost.Regex pour effectuer des recherches de chaîne régulière. Elle convertit les éléments de base de Markdown en HTML en utilisant des balises HTML correspondantes. Assurez-vous de prendre en compte les dépendances de Boost avant de lancer le code. Si vous rencontrez des problèmes de compilation, vous devrez peut-être compiler Boost en utilisant un outil comme CMake.

