```gdscript
extends KinematicBody

export var speed = 6.0
export var mouse_sensitivity = 0.005

var velocity = Vector3.ZERO
var direction = Vector3.FORWARD

func _ready():
    # Ajoute un événement de changement de taille pour adapter la caméra
    $Camera2D.set_as_current()
    $Camera2D.make_current()
    $Camera2D.set_orthogonal_size(1024, 768)

func _unhandled_input(event):
    if event.is_action_pressed("ui_cancel"):
        get_tree().quit()

func _input(event):
    if event.is_action_pressed("ui_cancel"):
        get_tree().quit()

    if event.is_action("move_forward"):
        direction = -transform.basis.z
    elif event.is_action("move_backward"):
        direction = transform.basis.z
    elif event.is_action("move_left"):
        direction = -transform.basis.x
    elif event.is_action("move_right"):
        direction = transform.basis.x
    elif not event.is_action_pressed("move_forward") and not event.is_action_pressed("move_backward") and not event.is_action_pressed("move_left") and not event.is_action_pressed("move_right"):
        direction = Vector3.ZERO

    if event is InputEventMouseMotion and Input.get_mouse_mode() == Input.MOUSE_MODE_CAPTURED:
        rotation_degrees.y -= event.relative.x * mouse_sensitivity
        rotation_degrees.x -= event.relative.y * mouse_sensitivity
        rotation_degrees.x = clamp(rotation_degrees.x, -90, 90)

func _physics_process(delta):
    velocity = direction * speed
    move_and_slide(velocity)
```

